#!/usr/bin/env node
/**
 * 18 Nov 2026 (decision 018): copies the translators' files
 * docs/engineering/templates-i18n/<lang>.json (de ja es fr it pt zh vi) into
 * src/lib/will/template-translations.generated.ts, so the fixed texts Will and
 * Mia send exist in all nine languages exactly as the translators wrote them.
 * English is not copied: it lives in the code (locked by Jo) and a test checks
 * that SOURCE.json's `en` still equals it.
 *
 * Run after any change to a translation:  node scripts/build-template-translations.mjs
 * The generated file is checked in. Do not edit it by hand.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'docs/engineering/templates-i18n');
const LANGS = ['de', 'ja', 'es', 'fr', 'it', 'pt', 'zh', 'vi'];

const source = JSON.parse(readFileSync(join(dir, 'SOURCE.json'), 'utf8'));
const keys = Object.keys(source);
const files = Object.fromEntries(LANGS.map((l) => [l, JSON.parse(readFileSync(join(dir, `${l}.json`), 'utf8'))]));

const lines = [];
for (const key of keys) {
  lines.push(`  ${JSON.stringify(key)}: {`);
  for (const l of LANGS) {
    const v = files[l][key];
    if (typeof v !== 'string' || !v.trim()) throw new Error(`${l}.json has no text for ${key}`);
    lines.push(`    ${l}: ${JSON.stringify(v)},`);
  }
  lines.push('  },');
}

const out = `/* GENERATED by scripts/build-template-translations.mjs from docs/engineering/templates-i18n/. Do not edit. */
export type TranslatedLang = ${LANGS.map((l) => `'${l}'`).join(' | ')};
export const TEMPLATE_TRANSLATIONS = {
${lines.join('\n')}
} as const satisfies Record<string, Record<TranslatedLang, string>>;
export type TemplateTranslationKey = keyof typeof TEMPLATE_TRANSLATIONS;
`;

writeFileSync(join(root, 'src/lib/will/template-translations.generated.ts'), out);
console.log(`wrote ${keys.length} keys x ${LANGS.length} languages`);
